INSERT INTO tags VALUES ('Monitoring & Status Pages', 'Software for [monitoring](https://en.wikipedia.org/wiki/Monitoring#Computing) systems, networks, applications and websites. ', '[]');
INSERT INTO tags VALUES ('Network Utilities', 'Network utilities are tools and software that help manage, monitor, and troubleshoot computer networks.', '[]');
INSERT INTO tags VALUES ('Note-taking & Editors', '[Note taking](https://en.wikipedia.org/wiki/Note-taking) editors.', '["Wikis"]');
INSERT INTO tags VALUES ('Office Suites', 'An [office suite](https://en.wikipedia.org/wiki/List_of_office_suites) is a collection of productivity software usually containing at least a word processor, spreadsheet and a presentation program.', '[]');
INSERT INTO tags VALUES ('Password Managers', 'A [password manager](https://en.wikipedia.org/wiki/Password_manager) allows users to store, generate, and manage their passwords for local applications and online services.', '[]');
INSERT INTO tags VALUES ('Pastebins', 'A [pastebin](https://en.wikipedia.org/wiki/Pastebin) is a type of online content-hosting service used for sharing and storing code and text.', '[]');
INSERT INTO tags VALUES ('Personal Dashboards', 'Dashboards for accessing information and applications.', '["Monitoring & Status Pages","Bookmarks and Link Sharing"]');
INSERT INTO tags VALUES ('Photo Galleries', 'A [gallery](https://en.wikipedia.org/wiki/Gallery_Software) is software that helps the user publish or share photos, pictures, videos or other digital media.', '["Static Site Generators","Media Streaming - Video Streaming","Content Management Systems (CMS)"]');
INSERT INTO tags VALUES ('Polls and Events', 'Software for organising [polls](https://en.wikipedia.org/wiki/Opinion_poll) and [events](https://en.wikipedia.org/wiki/Event).', '["Booking and Scheduling"]');
INSERT INTO tags VALUES ('Proxy', 'A [proxy](https://en.wikipedia.org/wiki/Proxy_server) is a server application that acts as an intermediary between a client requesting a resource and the server providing that resource. This section about forward (i.e. outgoing) proxies. For reverse proxies, see the Web Server section.', '["Web Servers"]');
INSERT INTO tags VALUES ('Recipe Management', 'Software and tools for managing [recipes](https://en.wikipedia.org/wiki/Recipe).', '[]');
INSERT INTO tags VALUES ('Remote Access', '[Remote desktop](https://en.wikipedia.org/wiki/Remote_desktop_software) and [SSH](https://en.wikipedia.org/wiki/Secure_Shell) servers and web interfaces for remote management of computer systems.', '[]');
INSERT INTO tags VALUES ('Resource Planning', 'Software and tools to help with [resource and supply planning](https://en.wikipedia.org/wiki/Resource_planning), including [enterprise resource and supply planning (ERP)](https://en.wikipedia.org/wiki/Enterprise_resource_planning).', '["Money, Budgeting & Management","Inventory Management"]');
INSERT INTO tags VALUES ('Search Engines', 'A [search engine](https://en.wikipedia.org/wiki/Search_engine_(computing)) is an [information retrieval system](https://en.wikipedia.org/wiki/Information_retrieval) designed to help find information stored on a computer system. This includes [Web search engines](https://en.wikipedia.org/wiki/Web_search_engine).', '[]');
INSERT INTO tags VALUES ('Self-hosting Solutions', 'Software for easy installation, management and configuration of self-hosted services and applications.', '[]');
INSERT INTO tags VALUES ('Software Development - API Management', '[API management](https://en.wikipedia.org/wiki/API_management) is the process of creating and publishing [application programming interfaces (APIs)](https://en.wikipedia.org/wiki/API), enforcing their usage policies, controlling access, nurturing the subscriber community, collecting and analyzing usage statistics, and reporting on performance. ', '[]');
INSERT INTO tags VALUES ('Software Development - Continuous Integration & Deployment', '[Continuous integration](https://en.wikipedia.org/wiki/Continuous_integration) and [Continuous deployment](https://en.wikipedia.org/wiki/Continuous_deployment) software and tools.', '["Automation"]');
INSERT INTO tags VALUES ('Software Development - FaaS & Serverless', '[Serverless computing](https://en.wikipedia.org/wiki/Serverless_computing), [Function as a Service (FaaS)](https://en.wikipedia.org/wiki/Function_as_a_service) and [Platform as a Service (Paas)](https://en.wikipedia.org/wiki/Platform_as_a_service) management software.', '[]');
INSERT INTO tags VALUES ('Software Development - Feature Toggle', 'A [feature toggle](https://en.wikipedia.org/wiki/Feature_toggle) in software development provides an alternative to maintaining multiple feature branches in source code.', '["Software Development - IDE & Tools"]');
INSERT INTO tags VALUES ('Software Development - IDE & Tools', 'An [integrated development environment (IDE)](https://en.wikipedia.org/wiki/Integrated_development_environment) is a software application that provides comprehensive facilities to computer programmers for software development.', '["Software Development - Low Code"]');
INSERT INTO tags VALUES ('Software Development - Localization', '[Localization](https://en.wikipedia.org/wiki/Internationalization_and_localization) is the process of adapting code and software to other languages.', '[]');
INSERT INTO tags VALUES ('Software Development - Low Code', 'A [low-code](https://en.wikipedia.org/wiki/Low-code_development_platform) development platform (LCDP) provides a development environment used to create application software through a graphical user interface.', '["Software Development - IDE & Tools"]');
INSERT INTO tags VALUES ('Software Development - Project Management', 'Tools and software for [software project management](https://en.wikipedia.org/wiki/Software_project_management).', '["Ticketing","Task Management & To-do Lists"]');
INSERT INTO tags VALUES ('Software Development - Testing', 'Tools and software for [software testing](https://en.wikipedia.org/wiki/Software_testing).', '[]');
INSERT INTO tags VALUES ('Software Development', '[Software development](https://en.wikipedia.org/wiki/Software_development) is the process of conceiving, specifying, designing, programming, documenting, testing, and bug fixing involved in creating and maintaining applications, frameworks, or other software components.', '[]');
INSERT INTO tags VALUES ('Static Site Generators', '[Static site generators](https://en.wikipedia.org/wiki/Web_template_system#Static_site_generators) generate full static HTML websites based on raw data, plain text files and a set of templates. ', '["Blogging Platforms","Photo Galleries","Content Management Systems (CMS)"]');
INSERT INTO tags VALUES ('Task Management & To-do Lists', '[Task management](https://en.wikipedia.org/wiki/Task_management#Task_management_software) software.', '["Software Development - Project Management","Ticketing"]');
INSERT INTO tags VALUES ('Ticketing', '[Helpdesk](https://en.wikipedia.org/wiki/Help_desk_software), [bug](https://en.wikipedia.org/wiki/Bug_tracking_system) and [issue](https://en.wikipedia.org/wiki/Issue_tracking_system) tracking software to help the tracking of user requests, bugs and missing features.', '["Task Management & To-do Lists","Software Development - Project Management"]');
INSERT INTO tags VALUES ('Time Tracking', '[Time-tracking software](https://en.wikipedia.org/wiki/Time-tracking_software) is a category of computer software that allows its users to record time spent on tasks or projects.', '[]');
INSERT INTO tags VALUES ('URL Shorteners', '[URL shortening](https://en.wikipedia.org/wiki/URL_shortening) is the action of shortening a [URL](https://en.wikipedia.org/wiki/Uniform_Resource_Locator) to make it substantially shorter and still direct to the required page. Before hosting one, please see [disadvantages](https://en.wikipedia.org/wiki/URL_shortening#Disadvantages) of URL shorteners.', '[]');
INSERT INTO tags VALUES ('Video Surveillance', 'Video surveillance, also known as [Closed-circuit television (CCTV)](https://en.wikipedia.org/wiki/Closed-circuit_television), is the use of video cameras for surveillance in areas that require additional security or ongoing monitoring.', '["Media Streaming - Video Streaming"]');
INSERT INTO tags VALUES ('VPN', 'A [virtual private network (VPN)](https://en.wikipedia.org/wiki/Virtual_private_network) extends a private network across a public network and enables users to send and receive data across shared or public networks as if their computing devices were directly connected to the private network.', '[]');
INSERT INTO tags VALUES ('Web Servers', 'Web Servers and Reverse Proxies. A [web server](https://en.wikipedia.org/wiki/Web_server) is a piece of software and underlying hardware that accepts requests via [HTTP](https://en.wikipedia.org/wiki/Hypertext_Transfer_Protocol) (the network protocol created to distribute web content) or its secure variant [HTTPS](https://en.wikipedia.org/wiki/HTTPS). A [Reverse Proxy](https://en.wikipedia.org/wiki/Reverse_proxy) is a proxy server that appears to any client to be an ordinary web server, but in reality merely acts as an intermediary that forwards requests to one or more ordinary web servers.', '["Proxy"]');
INSERT INTO tags VALUES ('Wikis', 'A [wiki](https://en.wikipedia.org/wiki/Wiki) is a publication collaboratively edited and managed by its own audience directly using a web browser.', '["Note-taking & Editors","Static Site Generators","Knowledge Management Tools"]');
